<?php
$role=role_name();$patient=patient_for_current_user();$doctor=doctor_for_current_user();$where=[];$params=[];if($role==='Patient'){$where[]='pr.patient_id=?';$params[]=$patient['patient_id'];}elseif($role==='Doctor'){$where[]='pr.doctor_id=?';$params[]=$doctor['doctor_id'];}if(get_string('q')!==''){$like='%'.get_string('q').'%';$where[]='(pr.prescription_number LIKE ? OR p.full_name LIKE ? OR u.full_name LIKE ?)';array_push($params,$like,$like,$like);}$sql="SELECT pr.*,p.patient_code,p.full_name patient_name,u.full_name doctor_name,c.diagnosis,(SELECT COUNT(*) FROM prescription_items pi WHERE pi.prescription_id=pr.prescription_id) item_count FROM prescriptions pr JOIN patients p ON p.patient_id=pr.patient_id JOIN doctors d ON d.doctor_id=pr.doctor_id JOIN users u ON u.user_id=d.user_id JOIN consultations c ON c.consultation_id=pr.consultation_id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY pr.issued_at DESC LIMIT 200";$stmt=db()->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();
?>
<div class="page-header"><div><h2>Prescriptions</h2><p>Digital prescriptions, medicine instructions and revision history.</p></div></div><div class="card mb-2"><form method="get" class="actions"><input type="hidden" name="page" value="prescriptions"><input class="input" style="max-width:320px" name="q" value="<?=e(get_string('q'))?>" placeholder="Prescription, patient or doctor"><button class="btn btn-light">Search</button></form></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Prescription</th><th>Patient</th><th>Doctor</th><th>Diagnosis</th><th>Medicines</th><th>Issued</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="table-title"><?=e($r['prescription_number'])?></div><div class="table-subtitle">Version <?=$r['version_number']?></div></td><td><?=e($r['patient_name'])?><div class="table-subtitle"><?=e($r['patient_code'])?></div></td><td><?=e($r['doctor_name'])?></td><td><?=e($r['diagnosis']??'—')?></td><td><?=$r['item_count']?></td><td><?=format_date($r['issued_at'],'d M Y, h:i A')?></td><td><a class="btn btn-primary btn-sm" href="<?=e(route_url('print-prescription',['id'=>$r['prescription_id']]))?>" target="_blank">View / Print</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty-state"><div class="empty-icon">✎</div><p>No prescriptions are available.</p></div><?php endif;?></div>
